import { GoogleGenAI } from "@google/genai";

export const PLAN_MODEL = "gemini-3.8-flash";

let client: GoogleGenAI | null = null;

function getClient(): GoogleGenAI {
    if (client === null) {
        client = new GoogleGenAI({ apiKey: process.env.GOOGLE_GENAI_API_KEY || "" });
    }
    return client;
}

export interface TravelPlan {
    intro: string;
    days: {
        day: number;
        title: string;
        activities: string[];
    }[];
    hiddenGem: {
        title: string;
        description: string;
    };
    localFood: {
        dish: string;
        description: string;
    };
}

export const GeminiService = {
    generateTravelPlan: async (destinationName: string, context?: string): Promise<TravelPlan | null> => {
        try {
            if (!process.env.GOOGLE_GENAI_API_KEY) {
                console.error("Gemini Service: Missing GOOGLE_GENAI_API_KEY");
                throw new Error("Missing Google API Key");
            }

            const prompt = `
        Act as an expert travel guide. Create a 3-day itinerary for ${destinationName} ${context ? `(${context})` : ''}.

        Requirements:
        - Tone: Enthusiastic, immersive, and practical.
        - Language: Spanish (Español).
        - Output Format: JSON ONLY. Do not use Markdown code blocks.

        JSON Schema:
        {
          "intro": "1 sentence hook",
          "days": [
            { "day": 1, "title": "Theme of the day (e.g. Historic Center)", "activities": ["Activity 1", "Activity 2", "Activity 3"] }
          ],
          "hiddenGem": { "title": "Name", "description": "Why it is special" },
          "localFood": { "dish": "Name", "description": "What is it" }
        }
      `;

            const response = await getClient().models.generateContent({
                model: PLAN_MODEL,
                contents: prompt,
                config: { responseMimeType: "application/json" },
            });
            const text = response.text ?? "";

            // console.log("Gemini JSON Response:", text); // Debug removed per user request

            return JSON.parse(text) as TravelPlan;

        } catch (error) {
            console.error("Gemini AI Error:", error);
            return null;
        }
    }
};
import { NextResponse } from 'next/server';
import { GeminiService } from '@/services/gemini';

export async function POST(request: Request) {
    try {
        const body = await request.json();
        const { destination, context } = body;

        if (!destination) {
            return NextResponse.json({ error: 'Destination is required' }, { status: 400 });
        }

        const plan = await GeminiService.generateTravelPlan(destination, context);
        return NextResponse.json({ plan });

    } catch (error) {
        console.error('API Plan Error:', error);
        return NextResponse.json({ error: 'Failed to generate plan' }, { status: 500 });
    }
}
import { describe, it, expect, vi, beforeEach } from "vitest";
import { VALID_ITINERARY_FIXTURE } from "./__fixtures__/itinerary.fixture";

const generateContent = vi.fn();

vi.mock("@google/genai", () => ({
  GoogleGenAI: class {
    models = { generateContent };
  },
}));

describe("GeminiService.generateTravelPlan", () => {
  beforeEach(() => {
    generateContent.mockReset();
    process.env.GOOGLE_GENAI_API_KEY = "test-key";
    vi.spyOn(console, "error").mockImplementation(() => {});
  });

  it("devuelve el plan cuando el modelo responde JSON válido", async () => {
    generateContent.mockResolvedValue({ text: JSON.stringify(VALID_ITINERARY_FIXTURE) });
    const { GeminiService } = await import("./gemini");
    const plan = await GeminiService.generateTravelPlan("Antigua");
    expect(plan?.days).toHaveLength(3);
    expect(generateContent).toHaveBeenCalledOnce();
  });

  it("devuelve null si falta la API key", async () => {
    delete process.env.GOOGLE_GENAI_API_KEY;
    const { GeminiService } = await import("./gemini");
    expect(await GeminiService.generateTravelPlan("Antigua")).toBeNull();
    expect(generateContent).not.toHaveBeenCalled();
  });
});
import { describe, it, expect, vi } from "vitest";
import type { TravelPlan } from "@/services/schemas";
import { VALID_ITINERARY_FIXTURE } from "@/services/__fixtures__/itinerary.fixture";

const generateTravelPlan = vi.fn<
  (destination: string, context?: string) => Promise<TravelPlan | null>
>(async () => VALID_ITINERARY_FIXTURE);

vi.mock("@/services/gemini", () => ({
  GeminiService: { generateTravelPlan },
}));

async function post(body: unknown) {
  const { POST } = await import("./route");
  return POST(new Request("http://localhost/api/ai-plan", { method: "POST", body: JSON.stringify(body) }));
}

describe("POST /api/ai-plan", () => {
  it("responde 400 sin destino", async () => {
    const res = await post({});
    expect(res.status).toBe(400);
  });

  it("devuelve el plan del servicio con 200", async () => {
    const res = await post({ destination: "Antigua" });
    expect(res.status).toBe(200);
    expect((await res.json()).plan.days).toHaveLength(3);
  });
});
